"""`fzp setup`：把 key-bindings（默认 Ctrl-T）写入 shell 配置文件。

机制与 fzf 的 `key-bindings.bash` 相同：readline 收到 Ctrl-T 时调用
`__fzp_select`，它先保存当前行内容，清空命令行后运行 fzp，选中结果
（相对路径）再填回命令行（默认补一个空格，可用 ^ 前缀追加模式）。
"""

from __future__ import annotations

import shlex
import shutil
import sys
from pathlib import Path

HEADER = "# >>> fzp key-bindings >>>"
FOOTER = "# <<< fzp key-bindings <<<"

# 注意：这段脚本由 bash 执行（readline 只支持 bash），
# 里面用条件判断保证在 zsh 下安静地不生效（zsh 用户请用 fzf 的 zsh 集成）。
SHELL_SNIPPET = r"""# >>> fzp key-bindings >>>
# Auto-generated by `fzp setup`. Remove this block to uninstall.
if [ -n "$BASH_VERSION" ]; then
  __fzp_select() {
    local item
    item="$(__FZP_COMMAND__)" || return
    if [ -n "$item" ]; then
      local prefix=${READLINE_LINE:0:READLINE_POINT}
      local suffix=${READLINE_LINE:READLINE_POINT}
      if [[ "$prefix" == *\^ ]]; then
        READLINE_LINE="${prefix%\^} ${item}${suffix}"
        READLINE_POINT=$(( ${#READLINE_LINE} - ${#suffix} ))
      else
        READLINE_LINE="${prefix}${item} ${suffix}"
        READLINE_POINT=$(( ${#READLINE_LINE} - ${#suffix} ))
      fi
    fi
  }
  bind -x '"\C-t": __fzp_select'
fi
# <<< fzp key-bindings <<<"""


def build_shell_snippet(command: str | None = None) -> str:
    """生成绑定脚本；命令使用安装时的绝对路径，避免交互 shell 的 PATH 差异。"""
    return SHELL_SNIPPET.replace(
        "__FZP_COMMAND__", command or detect_fzp_command()
    )


def detect_shell_rc(home: Path | None = None) -> Path:
    """根据 $SHELL 找到对应的 rc 文件，写不进去的 shell 直接报错。"""
    import os

    home = home or Path.home()
    shell_path = os.environ.get("SHELL", "")
    shell_name = Path(shell_path).name
    candidates = {
        "bash": home / ".bashrc",
        "zsh": home / ".zshrc",
    }
    rc = candidates.get(shell_name)
    if rc is None:
        raise RuntimeError(
            f"Unsupported shell {shell_path!r} (supported: bash, zsh). "
            "You can still use fzp without shell integration."
        )
    return rc


def inject_snippet(content: str, snippet: str | None = None) -> str:
    """把 snippet 注入到内容中：已存在则整体替换（幂等），否则追加到末尾。"""
    snippet = snippet or build_shell_snippet()
    if HEADER in content:
        start = content.index(HEADER)
        end = content.index(FOOTER) + len(FOOTER)
        return content[:start] + snippet + content[end:]
    if content and not content.endswith("\n"):
        content += "\n"
    return content + "\n" + snippet + "\n"


def setup_key_bindings(rc: Path | None = None, home: Path | None = None) -> Path:
    """写入 rc 文件，返回 rc 路径。重复执行是幂等的。"""
    rc = rc or detect_shell_rc(home)
    old = rc.read_text(encoding="utf-8") if rc.exists() else ""
    rc.write_text(inject_snippet(old), encoding="utf-8")
    return rc


def render_preview(content: str) -> str:
    """预览将要写入 rc 的内容（setup --show / --preview 用）。"""
    return inject_snippet(content)


def detect_fzp_command() -> str:
    """返回在交互 shell 中也能工作的 fzp 命令，并进行 shell quoting。

    直接运行入口脚本时记录它的绝对路径；通过 ``python -m fzp.cli``
    安装时则记录当前解释器，避免依赖虚拟环境是否已加入 PATH。
    """
    argv0 = Path(sys.argv[0])
    if argv0.name in {"fzp", "fzp.exe"} and argv0.is_file():
        return shlex.quote(str(argv0.resolve()))

    executable = shutil.which("fzp")
    if executable:
        return shlex.quote(str(Path(executable).resolve()))

    return f"{shlex.quote(sys.executable)} -m fzp.cli"
